import React, { useEffect, useState } from "react";
import axios from "axios";
import ReactQuill from "react-quill";
import 'react-quill/dist/quill.snow.css';
import toast, { Toaster } from "react-hot-toast";

export default function AdminAdmissionEditor() {
  const [content, setContent] = useState({
    applicationForm: "",
    applyOnline: "",
    feeStructure: ""
  });

  useEffect(() => {
    axios.get("http://localhost:5000/api/admissionsContent")
      .then(res => { if(res.data.success) setContent(res.data.data) })
      .catch(() => toast.error("Failed to load content"));
  }, []);

  const handleChange = (field, value) => setContent(prev => ({ ...prev, [field]: value }));

  const saveChanges = async () => {
    try {
      const res = await axios.put("http://localhost:5000/api/admissionsContent", content);
      if(res.data.success) toast.success("Admission page updated!");
    } catch(err) {
      console.error(err);
      toast.error("Failed to save changes");
    }
  };

  return (
    <div className="admin-editor">
      <Toaster />
      <h2>Edit Admissions Page</h2>

      <h3>Application Form</h3>
      <ReactQuill value={content.applicationForm} onChange={val => handleChange("applicationForm", val)} />

      <h3>Apply Online</h3>
      <ReactQuill value={content.applyOnline} onChange={val => handleChange("applyOnline", val)} />

      <h3>Fee Structure Notes</h3>
      <ReactQuill value={content.feeStructure} onChange={val => handleChange("feeStructure", val)} />

      <button className="save-btn" onClick={saveChanges}>💾 Save Changes</button>
    </div>
  );
}
